#!/usr/bin/env python3
"""Generate or verify the governing Decision index from authoritative front matter."""
from __future__ import annotations

import argparse
from pathlib import Path
import re

from governs_check import load_decisions

INDEX = Path("architecture/GOVERNING-DECISIONS.md")
ORDER = [
    "DeltaZulu.Kql", "DeltaZulu.Parse", "DeltaZulu.Forward",
    "DeltaZulu.LogCluster", "DeltaZulu.LocalStream",
    "DeltaZulu.DurableBuffer", "DeltaZulu.Agent", "DeltaZulu.Platform",
]
ESTATE = "Estate-wide (no single repository)"


def render_index() -> str:
    grouped: dict[str, list[str]] = {}
    for path, decision in load_decisions():
        source = path.read_text(encoding="utf-8")
        match = re.search(r"^# (DEC-\d{4})\s+[—-]\s+(.+)$", source, re.MULTILINE)
        if match is None or match.group(1) != decision["id"]:
            raise ValueError(f"{path}: missing or inconsistent Decision heading")
        subject = match.group(2).strip().replace("|", r"\|")
        row = (
            f"| [\`{decision['id']}\`](../{path.as_posix()}) | "
            f"{decision['status']} | {subject} |"
        )
        for name in decision["repos"] or [ESTATE]:
            grouped.setdefault(name, []).append(row)
    ordered = ORDER + sorted(set(grouped) - set(ORDER) - {ESTATE}) + [ESTATE]
    lines = [
        "# Governing Decisions by repository",
        "",
        "Generated by \`.github/scripts/governing_index.py --write\` from",
        "Decision front matter and headings. CI checks this file with \`--check\`.",
        "A Decision may govern multiple repositories and appear more than once.",
        "Only \`Accepted\` Decisions are binding. The existence checker validates",
        "explicit \`governs\` declarations, not semantic implementation.",
        "",
    ]
    for name in ordered:
        lines.extend([f"## {name}", ""])
        if name in grouped:
            lines.extend(["| Decision | Status | Subject |", "|---|---|---|"])
            lines.extend(sorted(grouped[name]))
        else:
            lines.append("_No Decision names this repository yet._")
        lines.append("")
    return "\n".join(lines)


def main() -> int:
    parser = argparse.ArgumentParser()
    group = parser.add_mutually_exclusive_group(required=True)
    group.add_argument("--check", action="store_true")
    group.add_argument("--write", action="store_true")
    args = parser.parse_args()
    try:
        expected = render_index()
        if args.write:
            INDEX.parent.mkdir(parents=True, exist_ok=True)
            INDEX.write_text(expected, encoding="utf-8")
            print(f"Regenerated {INDEX}")
            return 0
        if not INDEX.is_file() or INDEX.read_text(encoding="utf-8") != expected:
            print(f"::error file={INDEX}::Decision index differs from generated output; run --write")
            return 1
        print("Decision index matches source front matter and titles.")
        return 0
    except (ValueError, OSError) as exc:
        print(f"::error::{exc}")
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
